#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    const std::size_t n = points.size();
    int max_threads = 1;
#ifdef _OPENMP
    max_threads = omp_get_max_threads();
#endif

    std::vector<std::array<std::size_t, 4>> local(static_cast<std::size_t>(max_threads),
                                                  {0u, 0u, 0u, 0u});

#pragma omp parallel
    {
        int tid = 0;
#ifdef _OPENMP
        tid = omp_get_thread_num();
#endif
        auto &lb = local[static_cast<std::size_t>(tid)];

#pragma omp for
        for (std::size_t i = 0; i < n; ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Quadrants:
            // 0: x>=0, y>=0
            // 1: x<0,  y>=0
            // 2: x<0,  y<0
            // 3: x>=0, y<0
            if (x >= 0.0) {
                if (y >= 0.0) ++lb[0];
                else          ++lb[3];
            } else {
                if (y >= 0.0) ++lb[1];
                else          ++lb[2];
            }
        }
    }

    for (const auto &lb : local) {
        bins[0] += lb[0];
        bins[1] += lb[1];
        bins[2] += lb[2];
        bins[3] += lb[3];
    }
}
